"""Model-neutral Hermes tools over the exact artist-facing HTTP routes.

ASGI dispatch is in-process: no listening socket, separate provider client,
request model, generation ledger, or authorization bypass. Route validation,
finite errors and service guards are identical to Desktop REST requests.
"""
from __future__ import annotations

import importlib.util
import json
import sys
import threading
import typing
from pathlib import Path
from typing import Any

import httpx
from fastapi import FastAPI
from pydantic import BaseModel


