_LOAD_LOCK = threading.RLock()
_API_PATH = Path(__file__).with_name("dashboard") / "plugin_api.py"


def backend_api() -> Any:
    """Reuse this checkout's mounted facade; load once for CLI-only sessions."""
    with _LOAD_LOCK:
        mounted = sys.modules.get("hermes_dashboard_plugin_film-suite")
        if mounted is not None and getattr(mounted, "__file__", None) and Path(mounted.__file__).resolve() == _API_PATH.resolve() and hasattr(mounted, "router"):
            return mounted
        for module in tuple(sys.modules.values()):
            file = getattr(module, "__file__", None)
            if file and Path(file).resolve() == _API_PATH.resolve() and hasattr(module, "router"):
                return module
        name = "film_suite_agent_backend_api"
        spec = importlib.util.spec_from_file_location(name, _API_PATH)
        if spec is None or spec.loader is None:
            raise RuntimeError("The Continuo backend is unavailable")
        module = importlib.util.module_from_spec(spec)
        sys.modules[name] = module
        try:
            spec.loader.exec_module(module)
        except BaseException:
            sys.modules.pop(name, None)
            raise
        return module


def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def _query_schema(path: str) -> dict[str, Any]:
    """Only Request-parsed GET routes lack a Pydantic body schema."""
    properties: dict[str, Any] = {}
    required: list[str] = []
    if path in {"/image/edit/status", "/image/edit/result"}:
        properties["edit"] = {"type": "string", "pattern": r"^imgedit_[0-9a-f]{32}$"}
        required = ["edit", "scope"]
    if path in {"/image/preview/live", "/image/steps"}:
        properties["job"] = {"type": "string", "pattern": r"^imgjob_[0-9a-f]{32}$"}
        required = ["job", "scope"]
        extra = "since" if path == "/image/preview/live" else "step"
        properties[extra] = {"type": "integer", "minimum": 0, "maximum": 999999999999 if extra == "since" else 9999}
    if path == "/models/missing":
        return {"type": "object", "properties": {"workflow": {"type": "string", "pattern": r"^[a-z0-9][a-z0-9.\-]{0,79}$"}}, "required": [], "additionalProperties": False}
    if properties:
        properties["scope"] = {"type": "string", "pattern": r"^film_owner:(scratch|prj_[0-9a-f]{32})$"}
    return {"type": "object", "properties": properties, "required": required, "additionalProperties": False}


def _route_body_model(route: Any) -> Any:
    """The route's request model. Lane w30-fix3 item 0 (HER-091): a route declared before its model's area loads
    (music/evidence_1.py before music/models_1.py, string annotations) has no body_field at declaration time, but
    FastAPI resolves the model when it serves the request; read it from the endpoint's resolved hints the same way."""
    if route.body_field is not None:
        return route.body_field.field_info.annotation
    try:
        hints = typing.get_type_hints(route.endpoint)
    except Exception:
        return None
    models = [hint for key, hint in hints.items() if key != "return" and isinstance(hint, type) and issubclass(hint, BaseModel)]
    return models[0] if len(models) == 1 else None


def schemas_for(api: Any) -> dict[str, dict[str, Any]]:
    schemas = {}
    for name, method, path, description in ROUTE_TOOLS:
        route = next(route for route in api.router.routes if route.path == path and method in route.methods)
        body_model = _route_body_model(route) if method != "GET" else None
        parameters = body_model.model_json_schema(by_alias=True) if body_model is not None else _query_schema(path)
        # New agent submissions never take the legacy model-specific shortcut.
        if name == "continuo_video_submit":
            parameters["required"] = ["schema", "provider_id", "target_id", "client_request_id"]
            parameters["properties"]["schema"] = {"type": "string", "const": "studio.generation-request/1"}
        if name == "continuo_image_submit":
            parameters["required"] = [*parameters.get("required", []), "render_spec"]
        schemas[name] = {"name": name, "description": description, "parameters": parameters}
    return schemas


def _app_for(api: Any) -> FastAPI:
    app = FastAPI()
    app.include_router(api.router)
    return app


def _dispatch_target(api: Any, method: str, path: str, *, use_host: bool) -> tuple[Any, str, dict[str, str]]:
    return _app_for(api), path, {}


# Lane w19-g7hermes item 3 (HER-072; reference _handle_suite_action: ok only from the receipt): an answer is a failure
# when it carries an error or ok false, or when the answer, its details or its job names a failed state under state
# or status (a job read answers ok true with status "error"; a poll answers {"job": {"state": "failed"}}).
_FAILED_STATES = frozenset({"failed", "error", "moderated", "quarantined"})


def _answer_failed(data: Any) -> bool:
    if not isinstance(data, dict):
        return False
    if data.get("error") or data.get("ok") is False:
        return True
    for holder in (data, data.get("details"), data.get("job")):
        if isinstance(holder, dict) and any(isinstance(holder.get(key), str) and holder[key] in _FAILED_STATES for key in ("state", "status")):
            return True
    return False


def handlers_for(api: Any = None) -> dict[str, Any]:
    # Explicit api injection is for fixture parity; runtime resolves the host
    # facade at call time so Desktop mounting after tool registration cannot
    # leave tools attached to a second, unopened composition root.
    handlers = {}
    for name, method, path, _description in ROUTE_TOOLS:
        def make_handler(name: str, method: str, path: str):
            async def handle(args: dict[str, Any], **_kwargs: Any) -> str:
                try:
                    if type(args) is not dict:
                        return _json({"ok": False, "error": {"code": "invalid_agent_request", "message": "Tool arguments must be an object"}})
                    if name == "continuo_video_submit" and (
                        args.get("schema") != "studio.generation-request/1"
                        or any(type(args.get(key)) is not str or not args[key] for key in ("provider_id", "target_id", "client_request_id"))
                    ):
                        return _json({"ok": False, "error": {"code": "invalid_agent_request", "message": "Use a catalog target and a stable request ID"}})
                    if name == "continuo_image_submit" and type(args.get("render_spec")) is not dict:
                        return _json({"ok": False, "error": {"code": "invalid_agent_request", "message": "Use the catalog render_spec"}})
                    target_api = api if api is not None else backend_api()
                    app, request_path, headers = _dispatch_target(target_api, method, path, use_host=api is None)
                    # The route runs in this task (in-process ASGI): what it sends or writes is Hermes'.
                    caller = getattr(target_api, "_FILM_CALLER", None)
                    token = caller.set("hermes") if caller is not None else None
                    try:
                        from contextlib import nullcontext
                        scope_module = getattr(target_api, "_image_film_caller_scope_module", None)
                        marker = scope_module.trusted_agent_call() if scope_module is not None else nullcontext()
                        with marker:
                            transport = httpx.ASGITransport(app=app, raise_app_exceptions=False)
                            async with httpx.AsyncClient(transport=transport, base_url="http://127.0.0.1", trust_env=False, follow_redirects=False) as client:
                                response = await client.request(
                                    method, request_path, headers=headers, params=args if method == "GET" else None,
                                    json=args if method != "GET" else None,
                                )
                    finally:
                        if token is not None:
                            caller.reset(token)
                    try:
                        data = response.json()
                    except ValueError:
                        return _json({"ok": False, "http_status": response.status_code, "error": {"code": "agent_backend_unavailable", "message": "Continuo returned a non-JSON response"}})
                    failed = _answer_failed(data)
                    return _json({"ok": bool(response.is_success and not failed), "http_status": response.status_code, "data": data})
                except Exception:
                    # Never include arbitrary provider exception text or request
                    # bodies (which can carry paths and authentication data).
                    return _json({"ok": False, "error": {"code": "agent_backend_unavailable", "message": "The Continuo backend is unavailable"}})
            return handle
        handlers[name] = make_handler(name, method, path)
    return handlers


def register_route_tools(ctx: Any, *, api: Any = None) -> None:
    schema_api = api if api is not None else backend_api()
    handlers = handlers_for(api)
    for name, schema in schemas_for(schema_api).items():
        ctx.register_tool(
            name=name, toolset="continuo", schema=schema, handler=handlers[name],
            is_async=True, check_fn=_API_PATH.is_file, emoji="▣",
        )


# Song map (lane w6-song): the GET read takes song + approved_roots as query parameters (appended; the
# shared _query_schema above stays untouched and answers every other path).
_query_schema_before_song_map = _query_schema


def _query_schema(path: str) -> dict[str, Any]:  # noqa: F811 - append-only extension
    if path == "/music/song-map/status":
        return {"type": "object", "properties": {"job_id": {"type": "string", "pattern": r"^smap_[0-9a-f]{32}$"}},
                "required": ["job_id"], "additionalProperties": False}
    if path == "/music/song-map":
        return {"type": "object", "properties": {
            "song": {"type": "string", "minLength": 1, "maxLength": 4096, "description": "path of the sound file"},
            "approved_roots": {"type": "array", "items": {"type": "string"}, "maxItems": 32}},
            "required": ["song"], "additionalProperties": False}
    return _query_schema_before_song_map(path)


# Lane p5b-prj (charter decision 4): the song-map read also takes the project_id of the project whose folders the
# song lies in (appended; without it only the Loose-work folders count).
_query_schema_before_p5b_prj = _query_schema


def _query_schema(path: str) -> dict[str, Any]:  # noqa: F811 - append-only extension
    schema = _query_schema_before_p5b_prj(path)
    if path == "/music/song-map":
        schema = {**schema, "properties": {**schema["properties"], "project_id": {
            "type": "string", "pattern": r"^prj_[0-9a-f]{32}$", "description": "project whose approved folders hold the song"}}}
    return schema


# Lane w20-plan (planning layer base): the shot record, appended at the END (shared file, append-only). One record per
# project keyed by the script's shot id; the page's shot list, Board and shot details read and write the same routes.
ROUTE_TOOLS = ROUTE_TOOLS + (
    ("continuo_shot_plan_read", "POST", "/projects/shot-plan/read", "Read the project's shot record (studio.shot-plan/1): shots {sh-xxxxxxxx: {details {size, type, angle, move, equipment, lens mm, dur s, notes}, camera (previz: lens_mm, height_m, sensor_mm, pos, at), pictures [{item, role storyboard|keyframe|reference|previz|null}], elements [{key, version}], by, at}}, board_order {scene id: [shot ids]}, vocabulary (codes and names: size ECU CU MCU MCS MS MWS FS WS EWS INSERT; move; equipment incl. drone; lens 18 24 35 50 85 135) and revision. Shot ids come from continuo_script_read derived.shots. Pictures marked shot:<id> in Media join once (migrated). Read-only apart from that join."),
    ("continuo_shot_plan_write", "POST", "/projects/shot-plan/write", "Write the shot record exactly like the Script page: expected_revision (from the last read) and changes [{shot, details? (only the keys given change; null removes one), pictures? (replaces the list, order = board order of pictures, first = primary), elements? [{key, version?}], camera?}] and board? {scene, order [shot ids]} for one scene's card order. Codes from vocabulary only (Drone is equipment, not a move). Refusals: plan_conflict (re-read, then write again), size_unknown, type_unknown, angle_unknown, move_unknown, equipment_unknown, lens_out_of_range, dur_out_of_range, role_unknown, shot_invalid, board_invalid. Only when the artist asks for it."),
)


# Lane w20-plan item 6: elements with versions, appended at the END (shared file, append-only).
ROUTE_TOOLS = ROUTE_TOOLS + (
    ("continuo_elements_read", "POST", "/projects/elements/read", "Read the project's elements (studio.elements/1): [{key (name casefolded), name, kind character|place|prop, versions [{id v-xxxxxxxx, name (free, may be empty), pictures [Media item ids; first = primary]}], by, at}] and revision. The script's characters and places and the Media names (Use as reference...) appear on read (seeded). A shot picks a version per element in continuo_shot_plan_write elements [{key, version}]."),
    ("continuo_elements_write", "POST", "/projects/elements/write", "Write elements exactly like the Script inspector: expected_revision and changes [{key, name?, kind? character|place|prop, versions? (the full list: keep each existing version's id, a new version has no id; name free; pictures = Media item ids in order, first = primary)}] and remove [keys]. Add a prop with kind prop. Refusals: elements_conflict (re-read, then write again), kind_unknown, key_invalid, versions_empty, version_invalid, picture_invalid. Only when the artist asks for it."),
)


# Lane w20-plan2 (Previz stage 1), appended at the END (shared file, append-only). One previz set per scene
# (state/previz.json); the shot record stays the ONLY camera authority (owner steer, architecture review contract 2).
ROUTE_TOOLS = ROUTE_TOOLS + (
    ("continuo_previz_read", "POST", "/projects/previz/read", "Read a scene's previz set (studio.previz/1; scene = s-xxxxxxxx from continuo_script_read, omit for all): floor {w, d}, boxes [{id bx-, name, pos [x, y, z] centre, size [w, h, d], yaw}], figures [{id fig-, name, element el-?, version v-?, pos [x, z], yaw degrees (0 faces +z), pose stand|sit}], overrides {shot: {figure: {pos?, yaw?, pose?}}} (per-shot blocking), kept {shot: {item, sig}} (Keep frame), proposals (Hermes changes with state open|undone|dismissed|accepted), and cameras {shot: {lens_mm, sensor_w_mm, aspect, roll_deg, start {pos, at}, end? {pos, at}, height_m (derived)}} from the shot record. Units metres, y up."),
    ("continuo_previz_camera", "POST", "/projects/previz/camera", "Set one shot's previz camera exactly like the Previz inspector: expected_revision (continuo_previz_read shot_plan_revision), shot (sh-…) and camera {lens_mm 8-1200, start {pos [x, y, z], at [x, y, z]}, end? {pos, at} for a moving shot, aspect? \"16:9\", roll_deg?} in metres, y up (height = start.pos[1]); null clears it. Written to the shot record (the only camera); details.lens follows lens_mm. Hermes' change shows as a proposal the artist can undo (continuo_previz_review). Refusals: revision_required, previz_conflict (re-read), camera_invalid, camera_contradiction, lens_contradiction. Only when the artist asks for it."),
    ("continuo_previz_figure", "POST", "/projects/previz/figure", "Place, turn or pose one figure exactly like the Previz top view: scene, figure {id? (none = a new figure), name?, element? el-…, version? v-… (continuo_elements_read), pos? [x, z] metres, yaw? degrees, pose? stand|sit|walk}, and shot? (sh-…) to change it for that shot only (an override; the scene's figure stays). Shown to the artist as an undoable Hermes change. Refusals: figure_invalid, figure_unknown, camera_not_here. Only when the artist asks for it."),
    ("continuo_previz_block_scene", "POST", "/projects/previz/block", "Block a scene from the script as ONE proposal: figures for the people in it (linked to their character elements), a back wall (and a table indoors) when the set is empty, and a camera for every shot without one (distance from Size and Lens, height from Angle, an End for a moving shot). Existing figures, boxes and cameras stay. The artist sees the Hermes line with Undo and Dismiss; continuo_previz_review undoes it as long as nothing it touched was changed since. Only when the artist asks for it."),
    ("continuo_previz_write", "POST", "/projects/previz/write", "Change a scene's set exactly like the Previz inspector's Set section: expected_revision (continuo_previz_read revision), scene, set {floor? {w, d}, boxes? (the full list: keep ids; a new box has none), figures? (the full list), overrides? {shot: {figure: override|null}}, light? auto|day|dawn|dusk|night (auto = from the scene heading's INT/EXT and time of day; the Set section's Light), matte? 0-1 (the passepartout's opacity outside the frame; the Set section's Matte)}. Cameras are refused here (camera_not_here: use continuo_previz_camera). Refusals: previz_conflict (re-read), set_invalid, box_invalid, figure_invalid, override_invalid. Only when the artist asks for it."),
    ("continuo_previz_review", "POST", "/projects/previz/review", "Undo or dismiss an open previz proposal exactly like the Hermes line's Undo / Dismiss: action undo|dismiss, proposal? pr-… (default the newest open one). Undo restores the set and every camera the change touched only while they are as it left them; otherwise proposal_conflict and nothing changes. Refusals: proposal_unknown, proposal_conflict."),
)


# Lane w23-vsr (VID-153), appended at the END (shared file, append-only). RelayVSR is the default video upscaler;
# every setting is the artist's (and Hermes') own choice, exactly like the Video page's Upscale… box.
ROUTE_TOOLS = ROUTE_TOOLS + (
    ("continuo_video_upscale", "POST", "/generation/take/upscale", "Upscale one finished video take with RelayVSR into a NEW take (explicitly authorized, uses the local GPU), exactly like the Video page's Upscale…: client_request_id, studio_job_id of the source take, and any of model auto|x2|x4 (auto = x4 up to 576 px high, else x2), detail 0.00-1.00 (default 0.5; 1.0 invents texture, 0.5 is faithful and sharper than lanczos), size auto|native|1080p|1440p|2160p|custom (auto = 1080p for x4, native for x2; custom needs even width and height 64-8192), filter lanczos|bicubic|bilinear|area|nearest-exact (the downscale to the size), seed (0-4294967295, default 0; the same seed gives the same frames), in_frame/out_frame (both or neither); omitted settings come from the project's remembered choice, then the defaults. Plus save_to/requested_basename/approved_roots/project_id/project_ref like continuo_video_submit. Refused before any job with reason_code vsr_memory when frames x W x H x 12 bytes exceed the engine's free RAM above a 4 GB reserve (the message names both numbers and the fix: x2 or a shorter IN-OUT). Poll details.id with continuo_video_poll; its take facts carry upscale {relation upscales, source_job, model, detail, size, filter, seed, canvas, frames, fps}. The source stays untouched; the result lists in Media and Jobs and goes into the cut like any take. Settings are remembered per project."),
    ("continuo_video_upscale_settings", "POST", "/generation/take/upscale/settings", "Read (or remember) the RelayVSR video upscale settings exactly as the Upscale… box shows them: every option, the defaults, the project's remembered settings and, with studio_job_id, the source (width, height, frames, fps, audio), the plan (model, canvas, frames, filter) and memory {need_bytes, free_bytes, fits}. settings {model?, detail?, size?, width?, height?, filter?, seed?} previews a choice; remember true stores it for the project (project_id/project_ref). Starts nothing."),
)
# Lane w23-subs (CUT-173 / CUT-011): the cut's subtitle track ST1, appended at the END (shared file, append-only). The
# Cut page's Subtitles track, inspector and Deliver use the same routes; an edit by Hermes shows in the open Cut.
ROUTE_TOOLS = ROUTE_TOOLS + (
    ("continuo_subtitles_read", "POST", "/projects/subtitles/read", "Read the cut's subtitle track ST1 (studio.subtitles/1; timeline_id? default the active cut): revision, rate {num, den}, total_frames, cuts (V1 edit frames), track {enabled, style {preset classic|social, font sans|sans_bold|serif|mono, size % of frame height, color, highlight, background, background_opacity, outline, outline_color, x, y (% of the frame, y = bottom of the block), uppercase, active_word}, rules {max_chars, lines, min_seconds, max_seconds, cps, gap_frames, max_words, pause_seconds, linger_seconds, chain_seconds}}, cues [{id st-xxxxxxxx, start, end (record frames, end exclusive), text, words [{w, start, end}], lines (as shown), qc [cps|chars|short|long], edited, by}] and states (what shows on which frames)."),
    ("continuo_subtitles_apply", "POST", "/projects/subtitles/apply", "Edit the cut's subtitles exactly like the Cut page: expected_revision (from continuo_subtitles_read) and ops, applied together or not at all: set_text {id, text} (word times kept where words match), set_times {id, start?, end?} (record frames), move {id, delta} (frames), split {id, at_frame} (words before the frame stay left), merge {ids [neighbours]}, delete {id}, add {start, end, text}, set_track {preset? classic|social (resets style and rules), enabled?, locked? (a locked ST1 refuses every other edit with locked, like a locked V track), style? {keys of style}, rules? {keys of rules}}, resplit {in_frame?, out_frame?} (re-split unedited cues by the rules). Edited cues are kept by a later transcription. Refusals: subtitles_conflict (re-read), cue_unknown, overlap, split_outside, split_one_word, not_adjacent, text_empty, text_too_long, style_invalid, rules_invalid, preset_unknown, invalid_op, locked. Only when the artist asks for it."),
    ("continuo_subtitles_transcribe", "POST", "/projects/subtitles/transcribe", "Create subtitles from audio like the Cut menu's Create subtitles from audio: transcribes the cut's sound locally (faster-whisper large-v3 with word times, never a cloud service) and writes cues split by the track rules. Args: timeline_id?, range? {in_frame, out_frame} (default the whole cut), source dialogue (dialogue tracks + picture clips with sound on, default) | all (also music and effects), preset? classic|social (the look of a new track), wait_ms? (up to 20000). Answers a job {job_id subtx_..., state running|done|failed, progress, stage, result {revision, words, cues, replaced, added, kept_edited, language}}; poll continuo_subtitles_transcribe_status. Unedited cues in the range are replaced; edited cues stay. Refusals: no_dialogue, source_offline, asr_unavailable, invalid_range, timeline_not_found."),
    ("continuo_subtitles_transcribe_status", "POST", "/projects/subtitles/transcribe/status", "State of a Create subtitles from audio job: job_id (subtx_...), wait_ms? (up to 20000, waits while it runs). Answers {job_id, state running|done|failed, progress, stage, result, error}. Refusal: job_unknown."),
    ("continuo_subtitles_export", "POST", "/projects/subtitles/export", "Write the cut's subtitles as a file like Deliver's subtitle files: format srt|vtt, range? {in_frame, out_frame} (rebased to the range), name?, folder? (inside the project's approved folders; default the project output folder). Times are frame-exact against the cut. Answers {file (relative to the project), format, cues, revision, text}. Refusals: no_subtitles, folder_outside_roots, export_failed. Films and packages with subtitles: continuo_timeline_export subtitles files|burn|off."),
)
